//! Identifiers. All are plain values, serde-encodable, cheap to copy.

use serde::{Deserialize, Serialize};
use std::fmt;

/// Globally unique node (inode) identity, stable across renames and hosts.
///
/// Generated by whoever creates the node, with no server round trip, so that
/// offline creates work: high 64 bits = the creating host's `HostId`, low 64
/// bits = that host's monotonic counter (persisted in its state DB). The
/// root directory of every root is `NodeId::ROOT`.
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub struct NodeId(pub u128);

impl NodeId {
    pub const ROOT: NodeId = NodeId(1);
    pub fn new(host: HostId, counter: u64) -> NodeId {
        NodeId(((host.0 as u128) << 64) | counter as u128)
    }
    pub fn host(self) -> HostId {
        HostId((self.0 >> 64) as u64)
    }
}

impl fmt::Debug for NodeId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if *self == NodeId::ROOT {
            write!(f, "node:root")
        } else {
            write!(f, "node:{:x}.{:x}", (self.0 >> 64) as u64, self.0 as u64)
        }
    }
}

/// Server-assigned host identity (from enrollment; bound to the host's TLS
/// certificate). 0 is reserved for the server itself.
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Debug, Serialize, Deserialize)]
pub struct HostId(pub u64);

/// Identifies one root (namespace) on the server, e.g. "projects" or
/// "hosts/devbox/docker".
#[derive(Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Debug, Serialize, Deserialize)]
pub struct RootName(pub String);

/// Global, per-root, strictly increasing change sequence number. Every
/// committed op gets the next one. Also used as the "version" of whatever
/// the op touched.
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Debug, Default, Serialize, Deserialize)]
pub struct Seq(pub u64);

/// Server epoch: changes when the server's state is restored from backup or
/// otherwise rewound. A client whose epoch differs must fully resync.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Serialize, Deserialize)]
pub struct Epoch(pub u64);

/// Client-generated op id for idempotent retries: (host, per-host counter).
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Debug, Serialize, Deserialize)]
pub struct OpId {
    pub host: HostId,
    pub n: u64,
}

/// BLAKE3 hash. Identifies a blob or a chunk.
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub struct Hash(pub [u8; 32]);

impl Hash {
    pub fn of(data: &[u8]) -> Hash {
        Hash(*blake3::hash(data).as_bytes())
    }
    pub fn to_hex(&self) -> String {
        self.0.iter().map(|b| format!("{b:02x}")).collect()
    }
}

impl fmt::Debug for Hash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", &self.to_hex()[..12])
    }
}

/// What a file's content is. Identical content anywhere = identical id.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Serialize, Deserialize)]
pub enum ContentId {
    /// The empty file (no fetch ever needed).
    Empty,
    /// Whole file is one blob (size <= SMALL_FILE_MAX); hash of the bytes.
    Blob(Hash),
    /// Large file: hash of the encoded `Manifest`.
    Chunked(Hash),
}

/// Chunk list of a large file.
#[derive(Clone, PartialEq, Eq, Debug, Serialize, Deserialize)]
pub struct Manifest {
    pub size: u64,
    /// (chunk hash, chunk length) in file order.
    pub chunks: Vec<(Hash, u32)>,
}

impl Manifest {
    pub fn id(&self) -> ContentId {
        ContentId::Chunked(Hash::of(&crate::frame::encode(self).expect("manifest encodes")))
    }
}

/// Unix identity an op is performed as (asserted by the authenticated host,
/// then checked/mapped by the server per host rules; DESIGN §5.1).
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Serialize, Deserialize)]
pub struct Cred {
    pub uid: u32,
    pub gid: u32,
}
